mapper.select:
SELECT * FROM (
    SELECT h.*,
           (6371 * ACOS(
               LEAST(1, GREATEST(-1,
                   COS(RADIANS(#{lat})) * COS(RADIANS(h.lat)) * COS(RADIANS(h.lng) - RADIANS(#{lng}))
                   + SIN(RADIANS(#{lat})) * SIN(RADIANS(h.lat))
               ))
           )) AS distance
    FROM house h
    WHERE h.status = 1
      AND h.lat BETWEEN #{minLat} AND #{maxLat}
      AND h.lng BETWEEN #{minLng} AND #{maxLng}
) t
WHERE t.distance <= #{radius}
ORDER BY t.distance ASC
LIMIT #{limit}
